fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    if n == 1 {
        return a.clone(); // If the length is 1, return a clone of the input
    }
    
    let mut result = a.clone(); // Create a new vector with the same elements as `a`
    result[0] = a[n - 1]; // Set the first element to the last element of `a`
    result[n - 1] = a[0]; // Set the last element to the first element of `a`
    
    result // Return the modified vector
}